INSERT INTO `blog` VALUES (1, '不懂就问 这蛋是啥情况啊！！！', 8, 1, '2025-08-10 13:36:15', 'https://iblog-file.oss-cn-beijing.aliyuncs.com/files/ea7a44f10e9b417f8d2256e2947e03c2.png', NULL, 'https://iblog-file.oss-cn-beijing.aliyuncs.com/files/079e49a6681945d199a59f3645f1b5dc.mp4', '视频', '<p><span style=\"color: rgb(51, 51, 51); background-color: rgb(255, 255, 255); font-size: 16px;\">第一次看见这样的蛋，是小鸡要孵出来然后被煮了吗</span><img src=\"https://picasso-static.xiaohongshu.com/fe-platform/14b005f7afd5f7c88620478b610bf1de90c4ceab.png\" alt=\"\" data-href=\"\" style=\"height: 16px;\"/><img src=\"https://picasso-static.xiaohongshu.com/fe-platform/14b005f7afd5f7c88620478b610bf1de90c4ceab.png\" alt=\"\" data-href=\"\" style=\"height: 16px;\"/><img src=\"https://picasso-static.xiaohongshu.com/fe-platform/14b005f7afd5f7c88620478b610bf1de90c4ceab.png\" alt=\"\" data-href=\"\" style=\"height: 16px;\"/><img src=\"https://picasso-static.xiaohongshu.com/fe-platform/14b005f7afd5f7c88620478b610bf1de90c4ceab.png\" alt=\"\" data-href=\"\" style=\"height: 16px;\"/><img src=\"https://picasso-static.xiaohongshu.com/fe-platform/14b005f7afd5f7c88620478b610bf1de90c4ceab.png\" alt=\"\" data-href=\"\" style=\"height: 16px;\"/><img src=\"https://picasso-static.xiaohongshu.com/fe-platform/14b005f7afd5f7c88620478b610bf1de90c4ceab.png\" alt=\"\" data-href=\"\" style=\"height: 16px;\"/><span style=\"color: rgb(51, 51, 51); background-color: rgb(255, 255, 255); font-size: 16px;\">一瞬间食欲全无了</span></p>');
INSERT INTO `blog` VALUES (2, '你可以永远相信来自意大利的冰淇淋', 3, 1, '2025-08-06 15:38:42', 'https://iblog-file.oss-cn-beijing.aliyuncs.com/files/856dca0e17c748cca38921868949cf7f.jpg', NULL, '', '图片', '<p><span style=\"color: rgb(51, 51, 51); background-color: rgb(255, 255, 255); font-size: 16px;\">真的很好吃！很像新鲜的gelato了！里面是酸甜的树莓酱+奶味非常浓郁（超过mackie）+芝士蛋糕饼底碎，整体口感丝滑也不甜腻 抓紧时间去lidl买！不知道下周还会不会有了😭</span></p>');
INSERT INTO `blog` VALUES (3, '这样的葡萄谁看了不买！', 3, 1, '2025-08-06 15:39:35', 'https://iblog-file.oss-cn-beijing.aliyuncs.com/files/617c3322f8c44212a266f7054afab374.png', NULL, 'https://iblog-file.oss-cn-beijing.aliyuncs.com/files/c9de02d3e9a74bf888c033eb91850a57.mp4', '视频', '<p><span style=\"color: rgb(51, 51, 51); background-color: rgb(255, 255, 255); font-size: 16px;\">小时候的葡萄味，酸酸甜甜，一看到这种葡萄就想买！😘</span></p>');
INSERT INTO `blog` VALUES (4, '为啥我的干蒸牛肉会出很多水', 3, 1, '2025-08-06 15:40:53', 'https://iblog-file.oss-cn-beijing.aliyuncs.com/files/22009c5384b746a6a6f766ee0f1fa7c1.png', NULL, 'https://iblog-file.oss-cn-beijing.aliyuncs.com/files/b14b5764d7314c6d926cb1de0314aa3e.mp4', '视频', '<p><span style=\"color: rgb(51, 51, 51); background-color: rgb(255, 255, 255); font-size: 16px;\">是因为我蒸的时间太短没有把产生出的水分蒸干吗</span></p>');
INSERT INTO `blog` VALUES (5, '为什么现在大家化妆都很少画眼线了？', 4, 2, '2025-08-06 15:41:43', 'https://iblog-file.oss-cn-beijing.aliyuncs.com/files/161297513cb7486884263871c932620b.jpg', NULL, '', '图片', '<p><span style=\"color: rgb(51, 51, 51); background-color: rgb(255, 255, 255); font-size: 16px;\">难道是我的错觉吗？为什么感觉大家现在化妆很少画眼线了？朋友说她感觉画眼线压眼睛，显得眼睛更小了？但是画眼线不是可以让眼睛变得更大一些吗，怎么会显得眼睛更小呢，我有点get不到。。。</span></p>');
INSERT INTO `blog` VALUES (6, '这到底是做啥用的', 4, 2, '2025-08-06 15:42:58', 'https://iblog-file.oss-cn-beijing.aliyuncs.com/files/54ed33bd816a473c8b95ae35f117c6e2.jpg', NULL, '', '图片', '<p><span style=\"color: rgb(51, 51, 51); background-color: rgb(255, 255, 255); font-size: 16px;\">一直记得某一年买化妆品有个赠品是这样的东西(其实我也不知道是什么😬） 想找出来搅和粉底液用 找呀找呀就是找不到 最后在我初中的笔袋里找到了这一个 感谢我初中的时候总买点乱七八糟的东西 当时应该是准备拿来当镜子上学带着去臭美的😂不过那时候买过好几个 现在全都找不着了 隐约记得这个特别容易划花 还有我初中笔袋的样子 到现在也觉得好看 果然我的审美十几年没有什么变化 感谢网络闺蜜们，帮我确定了这个就是小镜子也确定了这一个是买化妆品送的，我自己买的那些全都找不到了我这个撕了膜了，就是这样模糊不清楚，所以我才一直不确定它到底是做什么用的</span></p>');
INSERT INTO `blog` VALUES (7, '一个疑惑：你们考研期间都化什么妆啊？', 4, 2, '2025-08-06 15:43:47', 'https://iblog-file.oss-cn-beijing.aliyuncs.com/files/ff48a3e78d384ffbb9504c6e08b2c550.jpg', NULL, '', '图片', '<p><span style=\"color: rgb(51, 51, 51); background-color: rgb(255, 255, 255); font-size: 16px;\">我感觉我自己学习学傻了，每天泡在当地图书馆里不能自拔，对着镜子里的自己看呆呆的，脸上没有一点起色，想早上早起化个精致的妆容改善下自己，可还要早起抢图书馆的座位😭考研搭子一直劝我，姐妹们，谁能给我个妆容参考下，感激不尽~</span></p>');
INSERT INTO `blog` VALUES (8, '替领导开会签完到提前跑了', 7, 3, '2025-08-06 15:46:34', 'https://iblog-file.oss-cn-beijing.aliyuncs.com/files/9328b1e595ae4b678fbefd0a8029013e.jpg', NULL, '', '图片', '<p><span style=\"font-size: 16px;\">替领导开会签完到提前跑了，结果没想到，人家还签退，领导被全县通报了 后续：今天领导见到我说，小萝啊，还要情况说明，我乖乖的写了情况说明给他审阅，这件事应该就这么过去了 没想到这个帖子火了，大家的祸都闯的五花八门，后续就是我给他写了情况说明，一会儿再给他送到县里去，他其实是有别的会冲突了，就派我去了个以为不太重要的视频会，他没想到我早跑，我也没想到会签退</span><span style=\"color: rgba(51, 51, 51, 0.6); font-size: 14px;\"><br></span></p>');
INSERT INTO `blog` VALUES (9, '叠纸游戏2026校园招聘正式启动！', 7, 3, '2025-08-06 15:47:21', 'https://iblog-file.oss-cn-beijing.aliyuncs.com/files/56b4a089d7784094b4f4a5ddf72d81ef.jpg', NULL, '', '图片', '<p><span style=\"color: rgb(51, 51, 51); background-color: rgb(255, 255, 255); font-size: 16px;\">🌟面向对象：2026届应届毕业生（毕业时间在2025.09-2026.08） 🌟网申时间：8月1日-10月31日 🌟岗位类别：程序技术类、美术表现类、产品策划类、市场运营类、IP开发类、质量管理类、游戏音频类、职能支持类</span></p>');
INSERT INTO `blog` VALUES (10, '求助 开车45分钟通勤的班要去吗？', 7, 3, '2025-08-06 15:49:52', 'https://iblog-file.oss-cn-beijing.aliyuncs.com/files/ecf91ead89c94824adabbcbf9d145343.webp', NULL, '', '图片', '<p><span style=\"color: rgb(51, 51, 51); background-color: rgb(255, 255, 255); font-size: 16px;\">如题，找到了个双休的工作，但是有点偏僻，坐车根本到不了，准备开车上班，8.30上班，通勤45分钟 我自己对于开车上班还有新鲜感，但是不知道会不会后面就很疲惫，求告知。</span></p><p><br></p><p><span style=\"color: rgb(51, 51, 51); background-color: rgb(255, 255, 255); font-size: 16px;\">大家的回复我都有看到，上班通勤真的是大家共同的殇，坚持那么久的都是超级厉害的人呀，太长通勤的也要照顾好自己哦，不要太辛苦了。 回到我本身，这份工作出现的时间太巧了，双休，工资也合适，听招聘方说工作量也不大，冬天还会延迟半小时上班。 对开车上班的新鲜感还在，以前在外地试过地铁公交单车，让我试试看开车上班吧！</span></p>');
INSERT INTO `blog` VALUES (11, '追星女就不可能辞职', 7, 3, '2025-08-06 15:51:39', 'https://iblog-file.oss-cn-beijing.aliyuncs.com/files/c3e0685e99ca42bf9e803d0f908c5ea8.png', NULL, 'https://iblog-file.oss-cn-beijing.aliyuncs.com/files/85322099df9443f88a6e0cb5c407453d.mp4', '视频', '<p><span style=\"color: rgb(51, 51, 51); background-color: rgb(255, 255, 255); font-size: 16px;\">附了原图，欢迎大家交作业 ps 上班时间完成，用的是公司的打印机，公司的剪刀，公司的创可贴卷一卷贴上的</span></p>');
INSERT INTO `blog` VALUES (12, '好像不小心和侠缘说漏嘴了', 6, 3, '2025-08-06 15:53:24', 'https://iblog-file.oss-cn-beijing.aliyuncs.com/files/47f33988566548ef9c2860f83b87d1f0.jpg', NULL, '', '图片', '<p><span style=\"color: rgb(51, 51, 51); background-color: rgb(255, 255, 255); font-size: 16px;\">晚上和侠缘一起觉的时候 我们再次聊到了结缘的话题 </span></p><p><span style=\"color: rgb(51, 51, 51); background-color: rgb(255, 255, 255); font-size: 16px;\">我依旧坚决的表示：我以后不进醉花阴</span></p><p><span style=\"color: rgb(51, 51, 51); background-color: rgb(255, 255, 255); font-size: 16px;\"> 我侠缘则仍然回复那句反驳：那你以后碰到更喜欢的人了怎么办？ </span></p><p><span style=\"color: rgb(51, 51, 51); background-color: rgb(255, 255, 255); font-size: 16px;\">我：我只喜欢你 </span></p><p><span style=\"color: rgb(51, 51, 51); background-color: rgb(255, 255, 255); font-size: 16px;\">我侠缘：你要是突然喜欢上别人了呢？ </span></p><p><span style=\"color: rgb(51, 51, 51); background-color: rgb(255, 255, 255); font-size: 16px;\">我：那就死 一系列重复的话术拉扯之后 </span></p><p><span style=\"color: rgb(51, 51, 51); background-color: rgb(255, 255, 255); font-size: 16px;\">我脑海忽然闪过一句话 我：你是不是喜欢上别人了？ </span></p><p><span style=\"color: rgb(51, 51, 51); background-color: rgb(255, 255, 255); font-size: 16px;\">我侠缘一直没接话 此时已经凌晨一点多 </span></p><p><span style=\"color: rgb(51, 51, 51); background-color: rgb(255, 255, 255); font-size: 16px;\">我不知道她是睡着了 还是沉默了 我不知道…</span></p>');
INSERT INTO `blog` VALUES (13, '从开口就冷场到句句点头，表达力让我翻盘', 8, 2, '2025-08-06 15:56:50', 'https://iblog-file.oss-cn-beijing.aliyuncs.com/files/bba481867b4b4edebd2bcbdf27917388.png', NULL, '', '图片', '<p><span style=\"color: rgb(51, 51, 51); background-color: rgb(255, 255, 255); font-size: 16px;\">心中有模板，脑中有框架，只要发言，张口就来 </span></p><p><span style=\"color: rgb(51, 51, 51); background-color: rgb(255, 255, 255); font-size: 16px;\">每天10分钟练口才，63天之后你会惊艳会所有人 </span></p><p><span style=\"color: rgb(51, 51, 51); background-color: rgb(255, 255, 255); font-size: 16px;\">巴菲特说:要学会演讲。这是一项可以持续使用五六十年的资产，如果你不喜欢演讲，就要承受五六十年的损失。 </span></p><p><span style=\"color: rgb(51, 51, 51); background-color: rgb(255, 255, 255); font-size: 16px;\">卡耐基说:一个人的成功85%靠他的人际沟通和演说能力，只有15%靠他的专业技能 </span></p><p><span style=\"color: rgb(51, 51, 51); background-color: rgb(255, 255, 255); font-size: 16px;\">马云说:如果你不会说话，你的人生就是十分耕耘一分收获。如果你学会说话，就是一分耕耘十分收获。 </span></p><p><span style=\"color: rgb(51, 51, 51); background-color: rgb(255, 255, 255); font-size: 16px;\">平时讲话自然流畅，一到台上就慌了神，一紧张就掉链子，怎么办？ </span></p><p><span style=\"color: rgb(51, 51, 51); background-color: rgb(255, 255, 255); font-size: 16px;\">来学表达，学会了如同安上了一双翅搒，任何地方不怯场，自信、又把自己的观点通过表达种在别人心中，生根发芽。 </span></p><p><span style=\"color: rgb(51, 51, 51); background-color: rgb(255, 255, 255); font-size: 16px;\">学会当众讲话，提升表达影响力! </span></p><p><span style=\"color: rgb(51, 51, 51); background-color: rgb(255, 255, 255); font-size: 16px;\">只要你敢于发出声音，就会有观众和粉丝，有追随者!加入表达创富营改变从此刻发生...</span></p>');
INSERT INTO `blog` VALUES (14, 'crush深夜在朋友圈发美照吸引男人如何调理', 8, 2, '2025-08-06 15:57:59', 'https://iblog-file.oss-cn-beijing.aliyuncs.com/files/2551ee0f81c047c0aa99a9f193b2de6c.jpg', NULL, '', '图片', '<p><span style=\"color: rgb(51, 51, 51); background-color: rgb(255, 255, 255); font-size: 16px;\">本人直女，在遇到这样的事情之前也没想到过人生竟然能如此戏剧化。 前期提要，本人小时候长时间患有一种影响外貌的疾病因此很一直很内向，也有点自卑，没怎么接触过异性。直到长大一些彻底摆脱了这种病，从此以后性情大变，成为了一种神奇的厚脸皮体质。有次在某个旅游景区打黑车的时候，一起拼车的帅哥真的是一眼踩在了小女子审美点上，白白净净的小脸加一副斯斯文文的眼镜，抓得恰到好处的微分碎盖配合眼角的泪痣，1.85(目测）的完美身高更是馋得小女子直呼快哉快哉，于是果断要到了帅哥微叉，旅游结束以后我们开始在网上热聊。 聊天以后发现他并非徒有其表，他很会聊天，风趣幽默，每次跟他聊天的愉快程度让我不禁怀疑这是不是老天专门针对我下的杀猪盘，但是在此等尤物的强烈吸引力面前，相信没有谁能抵制住这种诱惑，于是一场针对我的巨大服从性测试由此拉开了帷幕。 鄙人平时很喜欢视奸他的朋友圈，因为这位小帅哥深谙朋友圈美学，审美不错，拍出来的照片赏心悦目，多看两眼咱大女人才有力气讨生活，并且还十分情感丰富，生活中遇到的一些琐事也能被他扩写成一篇文笔细腻的小作文。由此引出了关键的部分，在一个夜深人静的夜晚，小女子朋友圈刷新出来一条十分吸引眼球的他的九宫格美照，看得人目眦欲裂，目瞪口呆，每一张都是极其美艳，直男根本无法想象的拍照姿势和角度，其娇媚程度令人叹服，配合着一段钓系情感文案：这个世界欠调教，我也是。此时再点进他的朋友圈(可能是手滑不小心给我分组分错了)，里面记录了他为各任前男友写的小作文，比如其中有一任是他的金主爸爸，帅气多金的老男人，但对他只有生理需求毫无情感；还有一任是顶帅情绪价值拉满的男大，但是玩的花在全国各地范围内均有男女老少形形色色的对象。 看完以后我五感尽失，就这么茫茫然地沉沉睡去了，第二天早上起来的时候发现他所有朋友圈我都看不到了。在下觉得他应该是发现给我分组分错了，于是单删了我，但是至今不敢去给他发消息验证。由此达成了隐藏结局——湾仔码头。</span></p>');
INSERT INTO `blog` VALUES (15, '杭州花店门面景观改造', 9, 1, '2025-08-06 15:59:13', 'https://iblog-file.oss-cn-beijing.aliyuncs.com/files/0021f224433142f2b5b52f6e33b9f309.jpg', NULL, '', '图片', '<p>改造中</p>');
INSERT INTO `blog` VALUES (16, '4.30号现版本唯一完美阵容，学会轻松王者！', 6, 4, '2025-08-06 16:00:01', 'https://iblog-file.oss-cn-beijing.aliyuncs.com/files/fb55cf64a62d461b84561925e70d087a.jpg', NULL, '', '图片', '<p><span style=\"color: rgb(51, 51, 51); background-color: rgb(255, 255, 255); font-size: 16px;\">🔥阵容优点：现版本唯一完美阵容，过渡简单平滑，中期强势提速 🔥阵容分析：现版本卡莎在独家的情况下绝对可以说是最强阵容，中期强势提速，后期三星后可以打一切阵容，是当之无愧的版本之子。通常阵容都有缺点，而卡莎作为当前版本的完美阵容，唯一的缺点就是，怕同行，三星不了。 基础构架： 【二星守】芮尔 卡莎 【三未来】潘森 卢锡安 肾 搭配挂件（以下方案选择其一） 【搭挂件】费德提克 厄运小姐 莫甘娜 剑魔 【搭星守】艾克+辛德拉（推荐辛德拉来得早或有星守转） 【搭护卫】盖伦+瑞雯（推荐外面物理较多或有护卫转时） ❗在七人口的时候组成基础构架再搭配两张，有星守转给女枪，有护卫转给潘森 ❗七人口整体二星后看数量和同行情况选择追三星卡莎芮尔，还是选择上八提质量 🔥运营技巧： 开局抢攻速，优先做出核心装电刃，其次是鬼索狂暴之刃 【2阶段】什么二星上什么，优选三未来，护卫迅捷过渡 【3阶段】3-2升6级，小搜组成基础构架+1挂件，如质量较高，则继续过渡到4阶段 【4阶段】4-1升7搜出大部分二星，根据转职情况，选择基础构架搭配方案，无转职选则搭两挂件 【5阶段】根据卡莎数量决定追3星或升8补费德提克等强力挂件 【6阶段】追出三星卡莎再升9，通常情况下三星卡莎足以吃鸡 🔥装备方面： 卡莎： 必备（启动装二选一）：鬼索狂暴之刃/朔极之矛 备选：电刃，珠光护手，科技枪，帽子 芮尔：龙牙，反甲，板甲，狂徒 副C厄运小姐：朔极之矛，珠光护手，巨人杀手，帽子等法系输出装 满足上诉装备后，多余装备分配如下： 稻草人：离子火花，珠光护手，鬼书 优选英雄强化（强度按先后顺序）： 芮尔的坚守防线 卡莎的多重射击 其他体系内强化 最强强化：好事成双（两个挂件选择再上一个芮尔和卡莎） 优选强化： 星守转职，珠光莲花，护卫转职，迅捷射手之心 其他尽量选战力海克斯，如：狩猎律动，源计划甲壳 经济海克斯只选择dd街区 黄金门票 写在最后：整个s8赛季，其实卡莎是最强的阵容，没有之一，贯穿整个s8-s8.5，比贾克斯还要毒瘤的存在，但由于金铲铲卡莎一直有bug，所以卡莎一直是最弱的阵容。在卡莎修复bug后，终于在金铲铲迎来了曙光，乘着玩的人不多，快冲！</span></p>');
INSERT INTO `blog` VALUES (17, '期中考学生考太差不用上课了', 1, 4, '2025-08-06 16:01:25', 'https://iblog-file.oss-cn-beijing.aliyuncs.com/files/7825895032f14000985be2a0bd79937b.jpg', NULL, '', '图片', '<p><span style=\"color: rgb(51, 51, 51); background-color: rgb(255, 255, 255); font-size: 16px;\">在机构兼职教初三物理 学生初二下学期期末考30多分 上课前老板跟我说他现在觉悟了，想好好学了 教了一个月（一星期一节课）后第一次月考48分，年级上进步了四五十名 但是分析试卷还是有好多重复讲过的题目做错了，把这些讲过做错了的分加上去可以考60，就定了60分为期中考目标 期中考前最后一次课他说这次考到欧姆定律前的知识，计算题考两道热学的。最后一节课就着重复习了热学部分（前几节课讲的电学） 最后期中考出来得了36分😢</span></p><p><span style=\"color: rgb(51, 51, 51); background-color: rgb(255, 255, 255); font-size: 16px;\">考完上课分析试卷他还沾沾自喜地说这个分数还进步了7名，把我都给气笑了 最后大题一道电学一道热学，基本没做出来 教的我也很心累，上课看似在认真的听，实则根本没有在动脑，重复讲了n多遍一会儿会一会儿不会。有时数学老师在隔壁给他上课，能听到数学老师被气得梆梆梆敲白板 本来是明早的课，突然说取消了，换老师了，虽然有点意外，但还是反思了一下自己教学中的不足 </span></p><p><span style=\"color: rgb(51, 51, 51); background-color: rgb(255, 255, 255); font-size: 16px;\">1.不成体系 物理教学时间不长，除了初三知识点，初二的遗忘较多。没有一个完整的上课体系，每次上课前都是先问学生想上哪部分，比较被动，知识东上一点西上一点，连贯性不足 2.不够严厉 基本没对学生发过火说过重话，有时学生状态不好（心不在焉）也只是温柔提醒一下，调整不过来也就不管顺着讲了 </span></p><p><span style=\"color: rgb(51, 51, 51); background-color: rgb(255, 255, 255); font-size: 16px;\">3.容易受学生情绪影响 另一个物理学生，从第一次上课就耷拉着脸，一脸不爽，挺聪明的学生，但上到后面就会不耐烦，做笔记什么的鬼画符，看到她的脸就很影响心情，后来也主动提出来不给她上课了 </span></p><p><span style=\"color: rgb(51, 51, 51); background-color: rgb(255, 255, 255); font-size: 16px;\">综上，虽然有一定问题，但教学过程中自己也做到认真负责，学生学不会真的很挫败啊 没事了，到月底彻底告别教培，跳出舒适圈</span></p>');
INSERT INTO `blog` VALUES (18, '不磨脚缎带', 2, 4, '2025-08-06 16:02:23', 'https://iblog-file.oss-cn-beijing.aliyuncs.com/files/7b74bc55c59441c78d97074b22701985.jpg', NULL, '', '图片', '<p>分享穿搭</p>');
INSERT INTO `blog` VALUES (19, '下一个风口：“东方玄学+中药、水晶手串”贼猛', 2, 4, '2025-08-06 16:03:20', 'https://iblog-file.oss-cn-beijing.aliyuncs.com/files/c144c43180e84054a1ee92e2a576e8ef.jpg', NULL, '', '图片', '<p><span style=\"color: rgb(51, 51, 51); background-color: rgb(255, 255, 255); font-size: 16px;\">在TikTok卖饰品，我靠“东方文化韵味”打了场翻身仗！爆了几千🥚！ 去年还在跟风卖流行款，卷到利润薄如纸，直到把普通白水手串包装成“月亮的眼泪·清透晶串”，配上东方chuan说故事和月光下的视频，三天卖光库存，才算摸到门道 中药手串+东方xuan学比水晶还猛！ 核心就是给饰品裹上“文化外衣”，这招让水晶、中药手串、银饰全爆单了！！ 具体怎么做给大家拆解一下 1️⃣水晶手串卖“自然意境”：改名“星辰守hu·白水串”，说它在东方文化里被视作自然纯粹的象征，能让人联想到澄澈的天地。视频拍模特在晨光中戴水晶做瑜伽，配风铃声，强调“天然矿物”“手工编织”，只提“营造宁静心境”，绝不说特殊作用 2️⃣中药手串卖“自然禅意”：檀香木串叫“沉境之息·冥xiang珠”，讲它在东方传统中常与静心时刻相伴，自带沉稳气息 视频拍熏香与旧书，模特戴串深呼吸，配颂钵音，突出“天然原木”“独特木纹”，只谈文化里的象征意义，不沾任何功效，但视频故事能让老外自己悟！ 3️⃣银饰卖“文化符号”：平安扣项链变“如意结·东方银饰”，说绳结是古老东方的吉祥符号，代表美好联结 视频拍老人编中国结、女孩戴链自信行走，强调“手工工艺”“传统符号现代演绎”，用“美好寓意”替代特殊说法 这套打法能成，关键在四点： 1️⃣老外对东方文化充满好奇，觉得有故事的东西够独特； 2️⃣卖的是情绪价值和文化体验，让饰品成为承载情感的物件 3️⃣天然、手工、独特性正对他们胃口 4️⃣精准打</span><a href=\"https://www.xiaohongshu.com/search_result?keyword=spirituality&amp;type=54&amp;source=web_note_detail_r10\" target=\"_blank\" style=\"text-align: start;\">#spirituality</a><span style=\"color: rgb(51, 51, 51); background-color: rgb(255, 255, 255); font-size: 16px;\"> </span><a href=\"https://www.xiaohongshu.com/search_result?keyword=easternwisdom%25E7%25AD%2589%25E6%25A0%2587%25E7%25AD%25BE%25E5%25BC%2595%25E6%25B5%2581&amp;type=54&amp;source=web_note_detail_r10\" target=\"_blank\" style=\"text-align: start;\">#easternwisdom等标签引流</a><span style=\"color: rgb(51, 51, 51); background-color: rgb(255, 255, 255); font-size: 16px;\">，且严守红线不谈任何功效类表述 现在看啥饰品都能加东方元素：素圈戒指讲“圆满”的寓意，珍珠叫“月魄凝华”的雅称。用老外能理解的“东方文化”语言包装这些元素，在饰品赛道就是降维打击！！</span></p>');
INSERT INTO `blog` VALUES (20, '我好爱这个反派！', 5, 5, '2025-08-06 16:04:51', 'https://iblog-file.oss-cn-beijing.aliyuncs.com/files/d88a5910ce1149d38879f477577927aa.jpg', NULL, '', '图片', '<p><span style=\"color: rgb(51, 51, 51); background-color: rgb(255, 255, 255); font-size: 16px;\">我好爱模范出租车2里的这个反派角色，我觉得他长的好帅啊！</span></p><p><span style=\"color: rgb(51, 51, 51); background-color: rgb(255, 255, 255); font-size: 16px;\">因为被人误导做了坏事，最后我觉得不算洗白 如果他先遇到的是主角团，一定会变得很好吧</span></p><p><span style=\"color: rgb(51, 51, 51); background-color: rgb(255, 255, 255); font-size: 16px;\">就连最后流泪的时候都是在回忆出租车行的日子，他其实非常需要真诚的同伴和关爱啊</span></p><p><span style=\"color: rgb(51, 51, 51); background-color: rgb(255, 255, 255); font-size: 16px;\">第三季能不能把他复活，让他多做好事赎罪啊啊啊</span></p>');
INSERT INTO `blog` VALUES (21, '底特律一周目结局记录', 5, 5, '2025-08-06 16:05:40', 'https://iblog-file.oss-cn-beijing.aliyuncs.com/files/6b4553a90010436faf83dd9a160f092e.png', NULL, 'https://iblog-file.oss-cn-beijing.aliyuncs.com/files/8593646a020b4b019a65eb81f27ae8cb.mp4', '视频', '<p><span style=\"color: rgb(51, 51, 51); background-color: rgb(255, 255, 255); font-size: 16px;\">马库斯领导革命胜利 Alex和卡拉存活 但是康纳中途就反库了</span></p><p><span style=\"color: rgb(51, 51, 51); background-color: rgb(255, 255, 255); font-size: 16px;\">感觉他那条线最精彩但是没打到</span></p>');
