INSERT INTO `blog` VALUES (26, '差点把我看呕了，旅顺博物馆这两古代尸体', 5, 1, '2025-08-10 13:30:27', 'https://iblog-file.oss-cn-beijing.aliyuncs.com/files/55f3e9bb86ae45368c7e1cc7ea4dbe23.png', NULL, 'https://iblog-file.oss-cn-beijing.aliyuncs.com/files/94e65fe2f80a47dbbe2db89b4d6c2172.mp4', '视频', '<p><span style=\"color: rgb(51, 51, 51); background-color: rgb(255, 255, 255); font-size: 16px;\">真的有点生理不适，皮肤都变成鱿鱼干了。</span></p>');
INSERT INTO `blog` VALUES (27, '抱歉，我家真的不接待剧组上门拍戏😅', 8, 1, '2025-08-10 13:31:25', 'https://iblog-file.oss-cn-beijing.aliyuncs.com/files/eebd24bf76e149f79e67d55fc8897c80.png', NULL, 'https://iblog-file.oss-cn-beijing.aliyuncs.com/files/eddeb897ad3243b3aff63d6195b8dbd6.mp4', '视频', '<p><span style=\"color: rgb(51, 51, 51); background-color: rgb(255, 255, 255); font-size: 16px;\">我的农村自建房陆续收到了不少短剧剧组的邀约 剧组联系说房子有点老洋房的味道， 想要租用几天拍摄… 🖐🏻位数的场地费虽然很可观！ 但仔细考虑了一下还是拒绝了！ 毕竟房子是自己住， 运输摄影器材难免会有磕碰 i人还是自己安安静静宅着才舒服～</span></p>');
INSERT INTO `blog` VALUES (28, '南京博物院你真的很人性化', 8, 1, '2025-08-10 13:32:54', 'https://iblog-file.oss-cn-beijing.aliyuncs.com/files/8ef22a50a1754bfa9649a81d43b111e4.jpg', NULL, '', '图片', '<p><span style=\"color: rgb(51, 51, 51); background-color: rgb(255, 255, 255); font-size: 16px;\">说实话，我逛了那么多博物馆，第一次在一个博物馆里看到了高峰期时，女生的专用卫生间，成功在3分钟之内上到了厕所，南博你好人性化</span></p>');
INSERT INTO `blog` VALUES (29, '武汉东湖磨山好美', 8, 1, '2025-08-10 13:33:45', 'https://iblog-file.oss-cn-beijing.aliyuncs.com/files/3fe79b5677fb4effb701bd0033c1b743.png', NULL, 'https://iblog-file.oss-cn-beijing.aliyuncs.com/files/bcd04decc87d4174956ce9cf482b5a58.mp4', '视频', '<p><span style=\"color: rgb(51, 51, 51); background-color: rgb(255, 255, 255);\">武汉东湖磨山好美</span></p>');
INSERT INTO `blog` VALUES (30, '千万别入坑', 6, 1, '2025-08-10 13:38:54', 'https://iblog-file.oss-cn-beijing.aliyuncs.com/files/d2df9cd8d09644208e3ff7b8728bbf61.jpg', NULL, '', '图片', '<p><span style=\"color: rgb(51, 51, 51); background-color: rgb(255, 255, 255); font-size: 16px;\">新买的华为平板，游戏党慎重入手，系统太封闭了。</span></p>');
INSERT INTO `blog` VALUES (31, '哇！台风来临前的家', 9, 1, '2025-08-10 13:40:38', 'https://iblog-file.oss-cn-beijing.aliyuncs.com/files/eaa28fce7f5f42b5a9e75c4b22bc46cc.png', NULL, 'https://iblog-file.oss-cn-beijing.aliyuncs.com/files/f4ee8a5011204ebeaecd848ce8c5230e.mp4', '视频', '<p><span style=\"color: rgb(51, 51, 51); background-color: rgb(255, 255, 255); font-size: 16px;\">傍晚到家7点多 推开家门后真的被美到 台风前的天空 真的是七彩的 匆忙的拍了几张live 分享调色盘给大家🎨</span></p>');
INSERT INTO `blog` VALUES (32, '小猫的自我介绍', 10, 5, '2025-08-06 16:10:32', 'https://iblog-file.oss-cn-beijing.aliyuncs.com/files/cd0230509ceb456abf34cbaabd321770.png', NULL, 'https://iblog-file.oss-cn-beijing.aliyuncs.com/files/d57db38ada744f6385e270646bc6754b.mp4', '视频', '<p><span style=\"color: rgb(51, 51, 51); background-color: rgb(255, 255, 255);\">这是来自小猫的自我介绍</span></p><p><br></p>');
INSERT INTO `blog` VALUES (33, '是暑假带娃观影的最佳选择呀', 5, 5, '2025-08-06 16:06:30', 'https://iblog-file.oss-cn-beijing.aliyuncs.com/files/251d8e04ebbf42bab0192ba650551499.png', NULL, 'https://iblog-file.oss-cn-beijing.aliyuncs.com/files/fd1e8a18bc154b43b628d332c4c9e60d.mp4', '视频', '<p><span style=\"color: rgb(51, 51, 51); background-color: rgb(255, 255, 255); font-size: 16px;\">大人儿童都能笑成一片， 只不过大人笑着笑着就沉默了， 因为真的很容易带入自身的现状， 那是因为真的很写实 （努力了好久还没上岸的样子， 面对最亲的人只能撒谎； 工作遇到困难， 面对父母只能报喜不报忧。） 从故事情节来说： 从我们熟知的故事出发， 除了有在西游世界的取经四人组， 还有另一个取经四人组。 让我们看到了西游故事的另一半。 从画面色调来说： 是真的对眼睛好啊， 草地、山间、乡村、水流等等 绿色调搭配真的好夏天 配色很美。 还有就是有的人物虽然只有寥寥几笔， 但是却能活灵活现体现出人物的灵魂。 看到结尾，突然想到取经路上的种种， 我们小时候看懂了吗？ 是我们知道的那样吗？ 大人物为了取得想要的效果， 是会为底层的草根的生存考虑的吗？ 最后引用片尾的一句话： “致我们都能活成自己想要的样子” 还有就是片中突然来一段陕北口音真的还蛮搞笑的哈哈哈哈哈哈哈哈哈😂</span></p>');
INSERT INTO `blog` VALUES (34, '一大早被巴黎警察这个纹身笑死了', 7, 1, '2025-08-10 13:35:05', 'https://iblog-file.oss-cn-beijing.aliyuncs.com/files/d351302e477b4111ba13e977d1a729ad.jpg', NULL, '', '图片', '<p><span style=\"color: rgb(51, 51, 51); background-color: rgb(255, 255, 255); font-size: 16px;\">纹身师傅也二， 顺序应该是 水木金火土 吧</span></p>');
